CREATE TABLE "ParkingCustomerContract" ("id" TEXT NOT NULL,"contractNumber" TEXT NOT NULL,"mallId" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"title" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"signedDate" TIMESTAMP(3),"startDate" TIMESTAMP(3) NOT NULL,"endDate" TIMESTAMP(3) NOT NULL,"billingDay" INTEGER NOT NULL DEFAULT 1,"paymentTermDays" INTEGER NOT NULL DEFAULT 15,"depositAmount" DOUBLE PRECISION NOT NULL DEFAULT 0,"currency" TEXT NOT NULL DEFAULT 'VND',"notes" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ParkingCustomerContract_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ParkingContractRate" ("id" TEXT NOT NULL,"contractId" TEXT NOT NULL,"vehicleType" TEXT NOT NULL,"registeredQuantity" INTEGER NOT NULL,"unitPrice" DOUBLE PRECISION NOT NULL,"excessUnitPrice" DOUBLE PRECISION NOT NULL,"effectiveFrom" TIMESTAMP(3) NOT NULL,"effectiveTo" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ParkingContractRate_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ParkingVehicleAdjustment" ("id" TEXT NOT NULL,"contractId" TEXT NOT NULL,"vehicleType" TEXT NOT NULL,"previousQuantity" INTEGER NOT NULL,"newQuantity" INTEGER NOT NULL,"effectiveDate" TIMESTAMP(3) NOT NULL,"reason" TEXT NOT NULL,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ParkingVehicleAdjustment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ParkingMonthlyStatement" ("id" TEXT NOT NULL,"contractId" TEXT NOT NULL,"period" TEXT NOT NULL,"periodStart" TIMESTAMP(3) NOT NULL,"periodEnd" TIMESTAMP(3) NOT NULL,"issueDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"dueDate" TIMESTAMP(3) NOT NULL,"subtotal" DOUBLE PRECISION NOT NULL,"adjustment" DOUBLE PRECISION NOT NULL DEFAULT 0,"totalAmount" DOUBLE PRECISION NOT NULL,"paidAmount" DOUBLE PRECISION NOT NULL DEFAULT 0,"status" TEXT NOT NULL DEFAULT 'UNPAID',"reconciliationStatus" TEXT NOT NULL DEFAULT 'PENDING',"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ParkingMonthlyStatement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ParkingMonthlyLine" ("id" TEXT NOT NULL,"statementId" TEXT NOT NULL,"vehicleType" TEXT NOT NULL,"registeredQuantity" INTEGER NOT NULL,"actualQuantity" INTEGER NOT NULL,"excessQuantity" INTEGER NOT NULL,"unitPrice" DOUBLE PRECISION NOT NULL,"excessUnitPrice" DOUBLE PRECISION NOT NULL,"baseAmount" DOUBLE PRECISION NOT NULL,"excessAmount" DOUBLE PRECISION NOT NULL,"totalAmount" DOUBLE PRECISION NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ParkingMonthlyLine_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ParkingDebtPayment" ("id" TEXT NOT NULL,"statementId" TEXT NOT NULL,"amount" DOUBLE PRECISION NOT NULL,"paidAt" TIMESTAMP(3) NOT NULL,"method" TEXT,"referenceNo" TEXT,"notes" TEXT,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ParkingDebtPayment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ParkingContractDocument" ("id" TEXT NOT NULL,"contractId" TEXT NOT NULL,"documentType" TEXT NOT NULL DEFAULT 'CONTRACT',"fileName" TEXT NOT NULL,"filePath" TEXT NOT NULL,"fileSize" INTEGER NOT NULL,"mimeType" TEXT NOT NULL,"uploadedById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ParkingContractDocument_pkey" PRIMARY KEY ("id"));
